mapper.select:

		select TO_CHAR(rgtr_dt, 'YYYY-MM-DD HH24:MI:SS') as rgtr_dt,
		alarm_no,site_no,is_new,category,content
		 from om_alarm_log where 1=1 


	        AND site_no IN

	            CAST(#{item} AS INTEGER)



    		and is_new =#{is_new}


    		and category =#{category}


    		and EXTRACT(YEAR FROM rgtr_dt) =#{selectYear}


    		and EXTRACT(MONTH FROM rgtr_dt) =#{selectMonth}

    	order by rgtr_dt desc

    		limit #{limit}


			LIMIT #{size} OFFSET #{offset}

mapper.update:
		UPDATE om_alarm_log
    	SET is_new = #{is_new}
    	WHERE alarm_no = #{alarm_no}

	        AND site_no IN

	            CAST(#{item} AS INTEGER)
